Create PDF From HTML.code:
// Render HTML to a PDF. state.data will hold the PDF as a base64 string,
// ready to attach to an email or upload to a file store.
createPDF({
  html: `
    <h1>Payment Receipt</h1>
    <p>Beneficiary: ${$.data.beneficiaryName}</p>
    <p>Amount: ${$.data.amount} ${$.data.currency}</p>
    <p>Date: ${$.data.paidOn}</p>
  `,
  options: {
    format: 'A4',
    printBackground: true,
  },
});

Create PDF From URL.code:
// Print a web page to PDF.
createPDF({
  url: $.data.reportUrl, // e.g. a public dashboard link
  options: { format: 'A4', landscape: true },
  // Wait until the page's charts have finished loading.
  gotoOptions: { waitUntil: 'networkidle2', timeout: 60000 },
});

Take Screenshot.code:
// Capture a screenshot. Paths are relative to the Browserless baseUrl;
// the token is added for you.
request('POST', 'screenshot', {
  body: {
    url: $.data.dashboardUrl,
    options: { fullPage: true, type: 'png' },
    gotoOptions: { waitUntil: 'networkidle2' },
  },
  parseAs: 'base64', // state.data becomes a base64 image
});

Scrape Page Elements.code:
// Scrape elements from a rendered page.
request('POST', 'scrape', {
  body: {
    url: 'https://www.example.org/market-prices',
    elements: [
      { selector: 'table.prices tr' }, // one entry per CSS selector
      { selector: 'h1' },
    ],
    gotoOptions: { waitUntil: 'networkidle2' },
  },
});

Get Rendered HTML.code:
// Get the HTML of a page after JavaScript has run.
request('POST', 'content', {
  body: {
    url: $.data.pageUrl,
    gotoOptions: { waitUntil: 'networkidle2', timeout: 30000 },
  },
  parseAs: 'text',
});
